if (points.size() < 3) {
    throw std::runtime_error("At least 3 points are required to compute a best fitting plane.");
}

CGAL::linear_least_squares_fitting_3<Kernel> fitter;
fitter.set_points(points.begin(), points.end());
Kernel::Plane_3 plane = fitter.compute_plane();

return plane;

